import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"多労多得分配原理","description":"","frontmatter":{},"headers":[],"relativePath":"ja/06-多劳多得分配原理.md","filePath":"ja/06-多劳多得分配原理.md","lastUpdated":null}'),d={name:"ja/06-多劳多得分配原理.md"};function i(o,t,h,n,s,u){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="多労多得分配原理" tabindex="-1">多労多得分配原理 <a class="header-anchor" href="#多労多得分配原理" aria-label="Permalink to &quot;多労多得分配原理&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>06</td></tr><tr><td>モジュール</td><td>総綱と核心設定</td></tr><tr><td>キーワード</td><td>多労多得、分配、貢献、聯産承包、公平と効率</td></tr></tbody></table><h2 id="第一節-多労多得の基本定義" tabindex="-1">第一節 多労多得の基本定義 <a class="header-anchor" href="#第一節-多労多得の基本定義" aria-label="Permalink to &quot;第一節 多労多得の基本定義&quot;">​</a></h2><p>多労多得は錨点共生文明の核心的な分配原則であり、修練資源、進化機会、社会的栄誉などの希少価値の分配において、個人または集団の共生ネットワークに対する実際の貢献を主要な根拠とすることを意味する。貢献が大きいほど分配の取り分が多く、貢献が小さいほど分配の取り分が少ない。多労多得は、労せずして得る略奪式分配に反対すると同時に、多寡にかかわらず同じ取り分を与える平均主義的分配にも反対する。</p><p>「労働」は共生文明において特定の内包を持ち、単なる肉体労働を指すだけでなく、修練の精進、知識の創造、技術革新、錨点の維持、文明の統治、種族間協力など、共生ネットワークに積極的に貢献するすべての活動を含む。「得」も単なる物質的資源を指すだけでなく、進化機会、錨点アクセス権、導師指導資格、位面探査優先権などの総合的な進化支援も含む。</p><h2 id="第二節-多労多得の理論的基礎" tabindex="-1">第二節 多労多得の理論的基礎 <a class="header-anchor" href="#第二節-多労多得の理論的基礎" aria-label="Permalink to &quot;第二節 多労多得の理論的基礎&quot;">​</a></h2><p>多労多得原則の確立は、以下の三重の理論的考慮に基づく：</p><h3 id="_2-1-インセンティブ理論-貢献には正のフィードバックが必要" tabindex="-1">2.1 インセンティブ理論：貢献には正のフィードバックが必要 <a class="header-anchor" href="#_2-1-インセンティブ理論-貢献には正のフィードバックが必要" aria-label="Permalink to &quot;2.1 インセンティブ理論：貢献には正のフィードバックが必要&quot;">​</a></h3><p>進化は継続的な投入を必要とするプロセスである。貢献と報酬が切り離されれば、個人は継続的な投入の動機を失い、共生ネットワーク全体の進化効率が低下する。多労多得は、貢献と報酬の間に正のフィードバック循環を構築することで、各生命が自身の潜在能力を最大限に発揮し、共生ネットワークのためにより多くの価値を創造することを奨励する。</p><h3 id="_2-2-公平理論-貢献による分配が最も基本的な公平" tabindex="-1">2.2 公平理論：貢献による分配が最も基本的な公平 <a class="header-anchor" href="#_2-2-公平理論-貢献による分配が最も基本的な公平" aria-label="Permalink to &quot;2.2 公平理論：貢献による分配が最も基本的な公平&quot;">​</a></h3><p>共生文明において、公平は平均を意味しない。真の公平とは、各生命の労働に見合った報酬を得ることである。刻苦の修練を通じて高い境界に達した修練者がより多くの資源と機会を得ることは、その労働に対する合理的な報酬である；いかなる努力もしようとしない個人が基本的保障しか得られないことも、公平の現れである。多労多得が保護するのは、勤勉者と創造者の権益である。</p><h3 id="_2-3-効率理論-資源は最も価値を創造できる場所に流れるべき" tabindex="-1">2.3 効率理論：資源は最も価値を創造できる場所に流れるべき <a class="header-anchor" href="#_2-3-効率理論-資源は最も価値を創造できる場所に流れるべき" aria-label="Permalink to &quot;2.3 効率理論：資源は最も価値を創造できる場所に流れるべき&quot;">​</a></h3><p>宇宙の修練資源は技術的手段を通じて継続的に増加させることができるが、特定の時空においては依然として有限である。多労多得メカニズムは、資源を優先的に貢献が大きく効率の高い個人と集団に分配し、有限の資源から最大の進化効能を生み出す。これは弱者の放棄ではなく、全体の進化効率に対する責任である——全体の効率が向上した後、弱者を支援するためのより多くの資源が存在する。</p><h2 id="第三節-貢献の定量化評価体系" tabindex="-1">第三節 貢献の定量化評価体系 <a class="header-anchor" href="#第三節-貢献の定量化評価体系" aria-label="Permalink to &quot;第三節 貢献の定量化評価体系&quot;">​</a></h2><p>多労多得原則を運用可能にするため、共生文明は体系的な貢献定量化評価体系を構築した：</p><table tabindex="0"><thead><tr><th>貢献タイプ</th><th>評価次元</th><th>定量化方式</th></tr></thead><tbody><tr><td>修練貢献</td><td>境界上昇速度、境界の高さ、修練突破の模範効果</td><td>錨点ネットワークが自動的に修練データを記録し、修練貢献値に換算</td></tr><tr><td>知識貢献</td><td>修練心得の公開共有、新功法の創造、理論研究成果</td><td>学術委員会が評価し、知識の影響力と革新性に基づいて値を付与</td></tr><tr><td>技術貢献</td><td>法則工学の技術革新、倍増果実応用の最適化、錨点ハードウェアの改善</td><td>技術委員会が評価し、技術の実用価値と普及範囲に基づいて値を付与</td></tr><tr><td>サービス貢献</td><td>導師指導時間、錨点維持作業量、文明統治への参与度</td><td>錨点ネットワークが自動的にサービス時間と質を記録し、サービス貢献値に換算</td></tr><tr><td>生態貢献</td><td>惑星生態修復、位面エネルギー循環改善、宇宙環境保護</td><td>生態委員会が評価し、生態改善の範囲と持続度に基づいて値を付与</td></tr><tr><td>協作貢献</td><td>異種族間協力プロジェクトへの参与度、万族共和事務への貢献</td><td>共和議会が評価し、協作の深さと成果に基づいて値を付与</td></tr></tbody></table><p>個人の総貢献値は各種貢献値の加重合計であり、ウェイトは文明の発展段階の必要性に応じて動的に調整される。貢献値は四半期ごとに一回決済され、次の四半期の資源分配の主要な根拠となる。</p><h2 id="第四節-聯産承包メカニズム" tabindex="-1">第四節 聯産承包メカニズム <a class="header-anchor" href="#第四節-聯産承包メカニズム" aria-label="Permalink to &quot;第四節 聯産承包メカニズム&quot;">​</a></h2><p>聯産承包は、修練資源分配の分野における多労多得原則の具体的な制度設計であり、その核心的な考え方は「生産をグループに請け負わせ、生産に連動して報酬を計算し、超過生産を奨励する」ことである。</p><h3 id="_4-1-基本運営方式" tabindex="-1">4.1 基本運営方式 <a class="header-anchor" href="#_4-1-基本運営方式" aria-label="Permalink to &quot;4.1 基本運営方式&quot;">​</a></h3><ol><li><strong>資源請負</strong>: 共生文明は一定区域内の修練資源（霊脈、薬田、エネルギー鉱脈など）を修練者グループまたは種族共同体に請け負わせる</li><li><strong>生産ノルマ</strong>: 資源の基礎生産能力と請負者の能力に基づき、合理的な生産ノルマを設定する</li><li><strong>生産連動報酬</strong>: 請負者が得る資源の取り分は実際の生産量に連動し、ノルマ達成で基礎取り分を得、超過生産分は比例に応じて奨励される</li><li><strong>自主経営</strong>: 請負者は反略奪原則と生態保護法規に違反しない限り、資源の開発と利用方式を自主的に決定する権利を有する</li></ol><h3 id="_4-2-聯産承包の優位性" tabindex="-1">4.2 聯産承包の優位性 <a class="header-anchor" href="#_4-2-聯産承包の優位性" aria-label="Permalink to &quot;4.2 聯産承包の優位性&quot;">​</a></h3><ul><li>集団資源の利用効率を請負者の個人的利益と直接連動させ、請負者が精を出して耕作することを奨励する</li><li>資源の平均分配によって引き起こされる「共有地の悲劇」を回避し、資源利用効率を向上させる</li><li>請負者は超過生産奨励のインセンティブの下、技術革新と管理最適化を行う動機を持つ</li><li>修練者に安定した資源獲得チャネルを提供し、略奪行為の経済的動機を減少させる</li></ul><h3 id="_4-3-リスク保障" tabindex="-1">4.3 リスク保障 <a class="header-anchor" href="#_4-3-リスク保障" aria-label="Permalink to &quot;4.3 リスク保障&quot;">​</a></h3><p>聯産承包はリスクを完全に請負者に転嫁するものではない。共生文明は「請負リスク保障基金」を設立し、不可抗力の自然災害、位面変動などの状況に遭遇した場合、請負者に基礎保障を提供し、偶発的な理由で基礎修練条件を失わないことを確保する。</p><h2 id="第五節-基礎保障と多労多得の均衡" tabindex="-1">第五節 基礎保障と多労多得の均衡 <a class="header-anchor" href="#第五節-基礎保障と多労多得の均衡" aria-label="Permalink to &quot;第五節 基礎保障と多労多得の均衡&quot;">​</a></h2><p>多労多得は、共生文明が完全な「ジャングル社会」であることを意味しない。逆に、多労多得は「人人有路」の基礎保障と結合してこそ、公平と効率の統一を実現できる。</p><p>共生文明は「進化基礎保障線」を設定し、各生命がその貢献の多寡にかかわらず、以下の基礎保障を得られることを確保する：</p><ul><li>三百套本源修練体系の基礎法門を無料で取得する権利</li><li>最低限度の修練資源配給（基礎修練と生存を維持するのに十分）</li><li>基礎医療と教育サービス</li><li>錨点ネットワークの最低レベルへのアクセス権</li></ul><p>基礎保障線の上では、資源分配は厳格に多労多得原則に従う。この「底線保障＋貢献による分配」の二層構造は、弱者の基礎進化権を保護すると同時に、強者の創造と貢献を奨励する。</p><h2 id="第六節-多労多得の異化を防止するメカニズム" tabindex="-1">第六節 多労多得の異化を防止するメカニズム <a class="header-anchor" href="#第六節-多労多得の異化を防止するメカニズム" aria-label="Permalink to &quot;第六節 多労多得の異化を防止するメカニズム&quot;">​</a></h2><p>多労多得は実践において異化のリスクに直面する可能性があり、共生文明は以下の防止メカニズムを構築した：</p><ul><li><strong>独占防止メカニズム</strong>: 個人または集団が資源を独占することで不合理な超過貢献を得ることを禁止し、独占禁止法に明確な規定がある</li><li><strong>世代間公平メカニズム</strong>: 貢献値は完全に相続できず、「貢献の世襲」による階層固定化を防止する</li><li><strong>貢献真実性審査</strong>: 錨点ネットワークが貢献データを相互検証し、虚偽の貢献を防止する</li><li><strong>動的調整メカニズム</strong>: 貢献評価のウェイトと基準は文明の発展必要性に応じて定期的に調整され、ある種類の貢献が過度に膨張することを防止する</li></ul><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>多労多得は錨点共生文明の分配制度の核心原則である。それは略奪主義の「強者がすべてを食う」とも異なり、平均主義の「大釜飯」とも異なる；逆に、基礎保障の上で、貢献に応じて資源と機会を分配し、公平と効率の統一を実現する。多労多得の究極的な目標は、各生命の労働に報酬があるようにし、各生命の潜在能力が十分に発揮されるようにすることである。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>08-人人有路保障体系 (人人有路保障体系)</li><li>22-资源分配联产承包机制 (資源分配聯産承包メカニズム)</li><li>41-共生劳动法 (共生労働法)</li></ul>',37)])])}const p=a(d,[["render",i]]);export{_ as __pageData,p as default};
